"""Build a source-labelled offline directory from seed and completed public reads."""
import json,re,unicodedata,urllib.parse,hashlib,gzip
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def norm(s):return re.sub('[^a-z0-9]','',unicodedata.normalize('NFKD',re.sub(r'\([^)]*\)','',s)).encode('ascii','ignore').decode().lower()).removeprefix('the')
seed=json.loads((ROOT/'backend/app/catalogue/unimatch_top500_seed.json').read_text())['universities']
INPUTS=ROOT/'scripts/catalogue/inputs'
def read_input(name):return gzip.decompress((INPUTS/(name+'.gz')).read_bytes())
source=json.loads(read_input('unimatch-public-universities.json'));wiki=json.loads(read_input('unimatch-enriched-identities.json'));domains=json.loads(read_input('unimatch-domain-directory.json'))
wi={x['seed_id']:x for x in wiki};idx={norm(x['name']):x for x in source};hi={x['description']:x for x in source if len(x.get('description',''))>120};di={norm(x['name']):x for x in domains}
aliases={'EPFL – École polytechnique fédérale de Lausanne':'École Polytechnique Fédérale de Lausanne','Universiti Malaya (UM)':'University of Malaya','Ludwig-Maximilians-Universität München':'LMU Munich','University of Illinois Urbana-Champaign':'University of Illinois at Urbana-Champaign','Trinity College Dublin, The University of Dublin':'Trinity College Dublin','The University of Osaka':'Osaka University','Freie Universitaet Berlin':'Free University of Berlin','KIT, Karlsruhe Institute of Technology':'Karlsruhe Institute of Technology','Alma Mater Studiorum - Università di Bologna':'University of Bologna','Humboldt-Universität zu Berlin':'Humboldt University of Berlin','National Tsing Hua University - NTHU':'National Tsing Hua University','Technische Universität Berlin (TU Berlin)':'Technical University of Berlin','Universitat de Barcelona':'University of Barcelona',"Queen's University at Kingston":'Queen’s University','Universitas Indonesia':'University of Indonesia','Università di Padova':'University of Padua','Gadjah Mada University':'Universitas Gadjah Mada','Politecnico di Torino':'Polytechnic University of Turin','Universität Hamburg':'University of Hamburg','Friedrich-Alexander-Universität Erlangen-Nürnberg':'University of Erlangen-Nuremberg','Indian Institute of Science (IISc) Bangalore':'Indian Institute of Science','University of Massachusetts Amherst':'University of Massachusetts','University of Witwatersrand':'University of the Witwatersrand','Universität Stuttgart':'University of Stuttgart','Universität Innsbruck':'University of Innsbruck','University of Rome "Tor Vergata"':'University of Rome II   Tor Vergata','Sabanci University':'Sabancı University','Indiana University Bloomington':'Indiana University','Université de Liège':'University of Liège','Goethe-University Frankfurt am Main':'Goethe University Frankfurt','National University of Sciences & Technology (NUST) Islamabad':'National University of Sciences and Technology','Northeastern University':'Northeastern University, US','Università Cattolica del Sacro Cuore':'University Cattolica del Sacro Cuore','Ruhr-Universität Bochum':'Ruhr University Bochum','University at Buffalo SUNY':'University at Buffalo','Universität Konstanz':'University of Konstanz','Julius-Maximilians-Universität Würzburg':'University of Würzburg','Universitat Politècnica de Catalunya · BarcelonaTech (UPC)':'Universitat Politècnica de Catalunya','Universitat de Valencia':'University of Valencia','Université de Strasbourg':'University of Strasbourg','USI - Università della Svizzera italiana':'University della Svizzera italiana','Johannes Kepler University Linz':'Johannes Kepler University of Linz','Universidad de Costa Rica':'University of Costa Rica','Università Vita-Salute San Raffaele':'Vita-Salute San Raffaele University','Stony Brook University, State University of New York':'Stony Brook University','Universitas Padjadjaran (UNPAD)':'Padjadjaran University','Johannes Gutenberg Universität Mainz':'Johannes Gutenberg University of Mainz'}
aliases.update({'Universidad de los Andes':'University of the Andes, Colombia','Universitat Pompeu Fabra (Barcelona)':'Pompeu Fabra University','Universidade Estadual de Campinas (Unicamp)':'University of Campinas','Radboud University':'Radboud University Nijmegen','Universidad Nacional de Colombia':'National University of Colombia','Universidad Carlos III de Madrid (UC3M)':'Carlos III University of Madrid','Universidade Nova de Lisboa':'NOVA University of Lisbon','Pontificia Universidad Catolica del Peru (PUCP)':'Pontifical Catholic University of Peru','Université Grenoble Alpes':'Grenoble Alpes University','LUT University':'Lappeenranta-Lahti University of Technology LUT','Universitat Politecnica de Valencia':'Polytechnic University of Valencia','Essex, University of':'University of Essex','Université de Montpellier':'Montpellier University','Universidad de Sevilla':'University of Seville'})
# Exact directory aliases reviewed against the completed Hipo snapshot.
domain_aliases={'The Ohio State University':'Ohio State University - Columbus','The University of Newcastle, Australia (UON)':'University of Newcastle','Université Paris 1 Panthéon-Sorbonne':'Université Panthéon-Sorbonne (Paris I)','University of Virginia':'University of Virginia, Charlottesville',"Taylor's University":"Taylor's University College",'Rutgers University–New Brunswick':'Rutgers University','University of Rome "Tor Vergata"':'University of Roma "Tor Vergata"','Sunway University':'Sunway University College','LUT University':'Lappeenranta University of Technology','Universitat Politecnica de Valencia':'Universidad Politécnica de Valencia','USI - Università della Svizzera italiana':'Universita della Svizzera Italiana'}
# Public institutional homepages read directly, separate from rate-limited Wikipedia.
site_overrides={'Western University':'uwo.ca','Southern University of Science and Technology (SUSTech)':'sustech.edu.cn','Satbayev University':'satbayev.university','Università Cattolica del Sacro Cuore':'unicatt.it','Saint Petersburg State University':'spbu.ru','Université PSL':'psl.eu','Institut Polytechnique de Paris':'ip-paris.fr','KFUPM':'kfupm.edu.sa','Institute of Science Tokyo':'isct.ac.jp','RUDN University':'rudn.ru','University of Chinese Academy of Sciences (UCAS)':'ucas.ac.cn','HSE University':'hse.ru','Shoolini University of Biotechnology and Management Sciences':'shooliniuniversity.com','Tashkent Institute of Irrigation and Agricultural Mechanization Engineers - National Research University (TIIAME-NRU)':'tiiame.uz','Kazan (Volga region) Federal University':'kpfu.ru'}
site_overrides.update({key:value['domain'] for key,value in json.loads((ROOT/'scripts/catalogue/directory_domain_aliases.json').read_text()).items()})
site_overrides.update({'Leiden University':'universiteitleiden.nl','Wageningen University & Research':'wur.nl','University of Lisbon':'ulisboa.pt','University of Navarra':'unav.edu','Université Paris Cité':'u-paris.fr','University of the Philippines':'up.edu.ph','University of Kent':'kent.ac.uk','Tampere University':'tuni.fi','Università Vita-Salute San Raffaele':'unisr.it','University of Bordeaux':'u-bordeaux.fr','City St George’s, University of London':'citystgeorges.ac.uk','Adelaide University':'adelaideuni.edu.au','Northeastern University':'northeastern.edu','University of Melbourne':'unimelb.edu.au','The University of Melbourne':'unimelb.edu.au'})
result=[]
for s in seed:
 w=wi[s['seed_id']];m=idx.get(norm(aliases.get(s['name'],s['name']))) or hi.get(s['short_history']);d=di.get(norm(domain_aliases.get(s['name'],aliases.get(s['name'],s['name'])))) or di.get(norm(w.get('encyclopedia_title') or '')) or di.get(norm((m or {}).get('name','')))
 domain=site_overrides.get(s['name']) or s.get('official_domain') or (d['domains'][0] if d and d.get('domains') else None)
 image=m.get('image_url') if m else None;kind='emblem' if image else None;image_source=s['sources']['stats_history'] if image else None
 if not image and w.get('image_candidates'):
  title=w['image_candidates'][0];image='https://commons.wikimedia.org/wiki/Special:FilePath/'+urllib.parse.quote(title.removeprefix('File:'))+'?width=160';kind='emblem';image_source=w['encyclopedia_url']
 if not image and domain:image='https://www.google.com/s2/favicons?domain='+urllib.parse.quote(domain)+'&sz=128';kind='site_icon';image_source='https://'+domain
 history=w['history'] if w.get('encyclopedia_title') else (m or {}).get('description') or s['short_history'];valid=(len(history)>60 and not history.startswith('It is a ') and history not in ['Description not found.'] and 'is a system of' not in history)
 result.append({'id':s['seed_id'],'name':s['name'],'country':s['country'],'city':s.get('city') or '', 'domain':domain,'website':('https://'+site_overrides[s['name']] if s['name'] in site_overrides else s.get('official_site')) or ('https://'+domain if domain else None),'image':image,'imageKind':kind,'imageSource':image_source,'history':history if valid else None,'historySource':(w['history_source'] if w.get('encyclopedia_title') else s['sources']['stats_history']) if valid else None,'founded':s.get('founded_year'),'type':s.get('institution_type'),'students':s.get('students_total'),'internationalPercent':s.get('international_students_pct'),'subjectAreas':(m or {}).get('subjects',[])[:12],'source':s['sources']['stats_history'],'snapshotDate':'2026-10-19','encyclopediaTitle':w.get('encyclopedia_title')})
overrides=json.loads((ROOT/'scripts/catalogue/identity_editorial_overrides.json').read_text())
for row in result:
 if row['id'] in overrides:
  patch=overrides[row['id']];assert patch.get('expected_name',row['name'])==row['name'];row.update({k:v for k,v in patch.items() if k!='expected_name'})
icons={}
for filename in ['universityIcons.receipt.json','universityOfficialIcons.receipt.json','universityEmblems.receipt.json','universityAlternativeIcons.receipt.json','universityCanonicalIcons.receipt.json','universityUpdatedIcons.receipt.json','universityDeclaredBrands.receipt.json','universityProgrammeIdentityImages.receipt.json']:
 path=ROOT/'frontend/src/data'/filename
 if path.exists():
  for icon in json.loads(path.read_text()):
   if icon['status']=='cached':icons[icon['id']]=icon
for row in result:
 if row['history']:
  text=row['history'].split('\n')[0].strip()
  if len(text)>900:
   end=text.rfind('. ',0,900);text=text[:end+1] if end>100 else text[:900].rsplit(' ',1)[0]+'…'
  elif text and text[-1] not in '.!?…':
   end=text.rfind('. ');text=text[:end+1] if end>70 else text.rsplit(' ',1)[0]+'…'
  row['history']=text
 icon=icons.get(row['id'])
 if icon and icon['domain']==row['domain']:
  row.update(image=icon['path'],imageKind=icon.get('kind','site_icon'),imageSource=icon.get('content_location') or row['website'])
  if icon.get('canonical_website'):row['website']=icon['canonical_website']
branding={}
for row in result:
 if row['image'].startswith('/'):
  for alias in [row['name'],re.sub(r'\s*\([^)]*\)','',row['name']),row.get('encyclopediaTitle') or '']:
   if alias:branding[re.sub(r'[^\w]','',unicodedata.normalize('NFKC',alias)).lower()]=row['image']
(ROOT/'frontend/src/data/universityBranding.json').write_text(json.dumps(branding,ensure_ascii=False,indent=2)+'\n')
(ROOT/'frontend/src/data/universityDirectory.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
summary={'count':len(result),'images':sum(bool(x['image']) for x in result),'local_images':sum(x['image'].startswith('/universities/') for x in result),'institutional_logos':sum(x['imageKind']=='institution_logo' for x in result),'emblems':sum(x['imageKind']=='emblem' for x in result),'site_icons':sum(x['imageKind']=='site_icon' for x in result),'histories':sum(bool(x['history']) for x in result),'official_sites':sum(bool(x['website']) for x in result),'wikipedia_limit':'HTTP429 after200 records; no retry; no completion claim for absent metadata','sources':[{'url':'https://raw.githubusercontent.com/Asjad-Ilahi/World-Universities-Data/main/updated_universities.json','sha256':hashlib.sha256(read_input('unimatch-public-universities.json')).hexdigest()},{'url':'https://raw.githubusercontent.com/Hipo/university-domains-list/master/world_universities_and_domains.json','sha256':hashlib.sha256(read_input('unimatch-domain-directory.json')).hexdigest()}],'attribution':'Wikipedia extracts: CC BY-SA, individual article link on every record. Emblems belong to their respective institutions; identity display only. Website icons identified separately. Historical imported statistics are not current admission requirements.'}
(ROOT/'frontend/src/data/universityDirectory.provenance.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary))
